{"command":["bash","-lc","python3 - <<'PY'
import json,glob,os
snap='/root/projects/open_source/zero/B96DF826-4BB2-4B62-97AB-6D84254C53D7/Scenario-15/alerts'
alerts=[]
for f in sorted(glob.glob(os.path.join(snap,'alerts_at_*.json'))):
    data=json.load(open(f))
    for a in data:
        if a.get('labels',{}).get('namespace')!='otel-demo':
            continue
        alerts.append({
            'name':a['labels'].get('alertname'),
            'severity':a['labels'].get('severity'),
            'state':a.get('state'),
            'activeAt':a.get('activeAt')
        })
# summarize
from collections import defaultdict
summary=defaultdict(list)
for a in alerts:
    summary[a['name']].append(a)
for name, items in summary.items():
    sev=items[0]['severity']
    states=set(i['state'] for i in items)
    times=[i['activeAt'] for i in items]
    print(name, sev, len(items), sorted(states)[0], times[0], times[-1])
PY"]}

